package vn.restaurant.ui;
import vn.restaurant.model.*;import vn.restaurant.service.*;import vn.restaurant.util.*;import javax.swing.*;import javax.swing.table.*;import java.awt.*;import java.util.*;
public class FrmThanhToanHoaDon extends JFrame {
 private final CtlThanhToanHoaDon ctl;private final JTextField search=new JTextField(19);private final DefaultTableModel model=new DefaultTableModel(new String[]{"Mã bàn","Tên bàn","Loại bàn","Trạng thái"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable table=new JTable(model);
 public FrmThanhToanHoaDon(CtlThanhToanHoaDon ctl){super("Quản lý nhà hàng - Thanh toán hóa đơn");this.ctl=ctl;setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1080,690);setMinimumSize(new Dimension(850,560));setLocationRelativeTo(null);
 JPanel root=Theme.panel(new BorderLayout());setContentPane(root);JLabel header=new JLabel("  🍽  Quản lý nhà hàng");header.setFont(Theme.FONT.deriveFont(Font.BOLD,22));header.setOpaque(true);header.setBackground(Theme.BLUE);header.setForeground(Color.WHITE);header.setPreferredSize(new Dimension(0,58));root.add(header,BorderLayout.NORTH);
 JPanel sidebar=new JPanel(new GridLayout(9,1,0,8));sidebar.setBackground(Theme.NAVY);sidebar.setBorder(BorderFactory.createEmptyBorder(25,12,25,12));sidebar.setPreferredSize(new Dimension(210,0));for(String name:new String[]{"Trang chủ","Quản lý bàn","Quản lý món ăn","Quản lý hóa đơn","Thanh toán hóa đơn","Quản lý nhân viên","Quản lý khách hàng","Thống kê","Cài đặt"}){JLabel item=new JLabel("  "+name);item.setFont(Theme.FONT);item.setOpaque(true);item.setBackground(name.equals("Thanh toán hóa đơn")?Theme.ORANGE:Theme.NAVY);item.setForeground(Color.WHITE);sidebar.add(item);}root.add(sidebar,BorderLayout.WEST);
 JPanel content=Theme.panel(new BorderLayout(0,20));content.setBorder(BorderFactory.createEmptyBorder(26,28,26,28));root.add(content,BorderLayout.CENTER);
 JPanel top=Theme.panel(new BorderLayout(0,20));top.add(Theme.title("Thanh toán hóa đơn"),BorderLayout.NORTH);JPanel filter=Theme.panel(new FlowLayout(FlowLayout.LEFT,12,12));filter.setBackground(Theme.LIGHT);filter.add(new JLabel("Tên bàn hoặc mã bàn:"));search.setFont(Theme.FONT);search.setPreferredSize(new Dimension(240,39));filter.add(search);JButton find=Theme.button("Tìm kiếm",true),refresh=Theme.button("Làm mới",false);filter.add(find);filter.add(refresh);top.add(filter,BorderLayout.CENTER);content.add(top,BorderLayout.NORTH);
 Theme.table(table);table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);content.add(new JScrollPane(table),BorderLayout.CENTER);JPanel bottom=Theme.panel(new FlowLayout(FlowLayout.RIGHT));JButton view=Theme.button("Xem hóa đơn",true);bottom.add(view);content.add(bottom,BorderLayout.SOUTH);
 find.addActionListener(e->{try{fill(ctl.timBan(search.getText()));if(model.getRowCount()==0)JOptionPane.showMessageDialog(this,"Không tìm thấy bàn phù hợp.");}catch(IllegalArgumentException ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Thông báo",JOptionPane.WARNING_MESSAGE);}});
 refresh.addActionListener(e->{search.setText("");fill(ctl.danhSachBan());});view.addActionListener(e->openInvoice());table.addMouseListener(new java.awt.event.MouseAdapter(){public void mouseClicked(java.awt.event.MouseEvent e){if(e.getClickCount()==2)openInvoice();}});fill(ctl.danhSachBan());}
 private void fill(java.util.List<ClsBan> list){model.setRowCount(0);for(ClsBan b:list)model.addRow(new Object[]{b.ma,b.ten,b.loai,b.trangThai});}
 private void openInvoice(){int row=table.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Vui lòng chọn bàn cần thanh toán.");return;}String id=model.getValueAt(table.convertRowIndexToModel(row),0).toString();try{new FrmChiTietHoaDon(this,ctl,ctl.layHoaDon(id),()->fill(ctl.danhSachBan())).setVisible(true);}catch(IllegalStateException ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Thông báo",JOptionPane.WARNING_MESSAGE);}}
}
